 static void Capture(string phase,bool layout){var env=Env();var cam=All().Select(t=>t.GetComponent<Camera>()).First(c=>c&&c.name=="Audit_Camera");var pos=cam.transform.position;var rot=cam.transform.rotation;var fov=cam.fieldOfView;var rows=new List<object>();var views=layout?JObject.Parse(File.ReadAllText(LayoutPath))["views"]:JObject.Parse(File.ReadAllText("Assets/VRMaintenanceResearch/AuditOutputs/V2/source_reference.json"))["views"];Directory.CreateDirectory(Out+"/"+phase);try{foreach(var v in views){cam.transform.position=layout?B(v["position"]):V(v["position"]);cam.transform.rotation=Quaternion.LookRotation(layout?B(v["target"])-cam.transform.position:V(v["forward"]),Vector3.up);cam.fieldOfView=(float?)v["fov"]??65;var hidden=new List<Renderer>();if((bool?)(v["cutaway"]??v["overallCutaway"])==true)foreach(var r in env.GetComponentsInChildren<Renderer>(true))if(r.enabled&&(r.bounds.min.y>3.5f||r.name.Contains("Ceiling")||r.name.Contains("Roof")||r.name.Contains("SideWall")||r.name.Contains("EndWall"))){r.enabled=false;hidden.Add(r);}var rt=new RenderTexture(1200,800,24,RenderTextureFormat.ARGB32);rt.Create();var previous=RenderTexture.active;var tex=new Texture2D(1200,800,TextureFormat.RGB24,false);try{RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1200,800),0,0);tex.Apply();string path=Out+"/"+phase+"/"+(string)v["name"]+".png";File.WriteAllBytes(path,tex.EncodeToPNG());rows.Add(new{path,position=A(cam.transform.position),cutaway=hidden.Count});}finally{RenderTexture.active=null;Object.DestroyImmediate(tex);rt.Release();Object.DestroyImmediate(rt);RenderTexture.active=previous;foreach(var r in hidden)r.enabled=true;}}}finally{cam.transform.SetPositionAndRotation(pos,rot);cam.fieldOfView=fov;}Write(phase+"_screenshots.json",rows);}
