 var activity=old.transform.Find("Factory_Activity");var animator=activity.GetComponentInChildren<Animator>(true);Check(animator,"No imported Animator");var clips=AssetDatabase.LoadAllAssetsAtPath(Folder+"/06_Factory_Activity.glb").OfType<AnimationClip>().ToArray();Check(clips.Length==1,"Require one deterministic clip");var clip=clips[0];Check(Mathf.Abs(clip.length-48)<.05f&&clip.isLooping,"Clip must loop at48 seconds");
