 foreach(var r in old.GetComponentsInChildren<Renderer>(true)){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++){var m=mats[i];Check(m,"Missing imported material "+r.name);string key=m.name.Replace(" (Instance)","");bool roomGlass=(key.IndexOf("Glass",StringComparison.OrdinalIgnoreCase)>=0||key.IndexOf("Glazing",StringComparison.OrdinalIgnoreCase)>=0)&&!r.transform.IsChildOf(old.transform.Find("Vehicles_Background"));if(roomGlass)mats[i]=glass;else if(shared.TryGetValue(key,out var existing))mats[i]=existing;else shared.Add(key,m);if(mats[i]!=m)changes.Add(new{renderer=r.name,slot=i,before=m.name,after=mats[i].name});}r.sharedMaterials=mats;PrefabUtility.RecordPrefabInstancePropertyModifications(r);if(!r.transform.IsChildOf(activity)){GameObjectUtility.SetStaticEditorFlags(r.gameObject,StaticEditorFlags.BatchingStatic|StaticEditorFlags.OccludeeStatic);} }
 var xr=All().Select(t=>t.GetComponent<Unity.XR.CoreUtils.XROrigin>()).Single(x=>x);var start=layout["views"].Single(v=>(string)v["name"]=="Training_Participant");xr.MatchOriginUpCameraForward(Vector3.up,B(start["target"])-B(start["position"]));xr.MoveCameraToWorldLocation(B(start["position"]));PrefabUtility.RecordPrefabInstancePropertyModifications(xr.transform);Write("participant_start.json",new{camera=A(xr.Camera.transform.position),rig=A(xr.transform.position),source="Training_Participant",existingRigPreserved=true});Physics.SyncTransforms();Write("collision_manifest.json",collisions);Write("material_reuse.json",new{sharedImportedFamilies=shared.Count,overrides=changes});EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"Save existing V2 scene failed");EditorSceneManager.OpenScene(ScenePath);Metrics("modified");Validate();Capture("modified",true);File.WriteAllText(Out+"/integration_complete.txt","INTEGRATION_COMPLETE");
