 static void Validate(){var env=Env();var rs=env.GetComponentsInChildren<Renderer>(true);var ts=All();var failures=new List<string>();if(rs.Length>1200)failures.Add("renderer reduction <35 percent");if(ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject))!=0)failures.Add("missing scripts");if(rs.Any(r=>r.sharedMaterials.Any(m=>!m)))failures.Add("missing materials");if(env.GetComponentsInChildren<MeshCollider>(true).Length!=0)failures.Add("MeshColliders");if(env.GetComponentsInChildren<Rigidbody>(true).Length!=0)failures.Add("decorative Rigidbodies");var layout=JObject.Parse(File.ReadAllText(LayoutPath));var paths=new List<object>();foreach(var p in (layout["walkability"]??new JArray()).Concat(layout["views"].Where(v=>((string)v["name"]).EndsWith("Participant")))){var foot=B(p["position"]);foot.y=(float?)p["floorY"]??0;var hitFloor=Physics.Raycast(foot+Vector3.up*.5f,Vector3.down,out var hit,1,~0,QueryTriggerInteraction.Ignore);var overlaps=Physics.OverlapCapsule(foot+Vector3.up*.25f,foot+Vector3.up*1.50f,.20f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.transform.IsChildOf(env.transform)).Select(c=>c.name).ToArray();bool pass=hitFloor&&Mathf.Abs(hit.point.y-foot.y)<.03f&&overlaps.Length==0;if(!pass)failures.Add("Walkability "+(string)p["name"]);paths.Add(new{name=(string)p["name"],position=A(foot),floorHit=hitFloor,floorY=hitFloor?hit.point.y:-999,overlaps,pass});}Write("acceptance.json",new{status=failures.Count==0?"PASS":"FAIL",failures,rendererBudget=1200,actualRenderers=rs.Length,walkability=paths});Check(failures.Count==0,string.Join("; ",failures));}
  static void WalkSweeps(){Check(!EditorApplication.isPlaying,"Exit Play Mode");Physics.SyncTransforms();var paths=new Dictionary<string,Vector2[]>{{"Training",new[]{new Vector2(-4.2f,-2.7f),new Vector2(-2.2f,-2.35f),new Vector2(-1.4f,-2.35f),new Vector2(0,-2.35f)}},{"Computer",new[]{new Vector2(0,-2.35f),new Vector2(0,3.6f),new Vector2(-1.4f,3.6f),new Vector2(-2.2f,3.6f),new Vector2(-4.45f,3.9f)}},{"Fan",new[]{new Vector2(0,3.6f),new Vector2(0,6.25f),new Vector2(1.4f,6.25f),new Vector2(2.1f,6.25f),new Vector2(2.4f,4.55f),new Vector2(4,4.55f)}}};var env=Env();var rows=new List<object>();bool all=true;int floorSamples=0;foreach(var path in paths){for(int n=1;n<path.Value.Length;n++){var p=path.Value[n-1];var q=path.Value[n];var a=new Vector3(-p.x,0,-p.y);var b=new Vector3(-q.x,0,-q.y);var d=b-a;var hits=Physics.CapsuleCastAll(a+Vector3.up*.35f,a+Vector3.up*1.5f,.28f,d.normalized,d.magnitude,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.transform.IsChildOf(env.transform)).Select(h=>h.collider.name).Distinct().ToArray();var overlaps=new[]{a,b}.SelectMany(x=>Physics.OverlapCapsule(x+Vector3.up*.35f,x+Vector3.up*1.5f,.28f,~0,QueryTriggerInteraction.Ignore)).Where(c=>c.transform.IsChildOf(env.transform)).Select(c=>c.name).Distinct().ToArray();bool floorPass=true;float maxFloorError=0;int count=Mathf.CeilToInt(d.magnitude/.1f);for(int j=0;j<=count;j++){var point=Vector3.Lerp(a,b,j/(float)Math.Max(count,1));var floors=Physics.RaycastAll(point+Vector3.up*.5f,Vector3.down,1,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.transform.IsChildOf(env.transform)).OrderBy(h=>h.distance).ToArray();floorSamples++;if(floors.Length==0)floorPass=false;else{maxFloorError=Mathf.Max(maxFloorError,Mathf.Abs(floors[0].point.y));floorPass&=Mathf.Abs(floors[0].point.y)<.01f;}}bool pass=hits.Length==0&&overlaps.Length==0&&floorPass;all&=pass;rows.Add(new{route=path.Key,segment=n,from=A(a),to=A(b),length=d.magnitude,radius=.28f,lowerCenter=.35f,upperCenter=1.5f,hits,overlaps,floorPass,maxFloorError,pass});}}Write("continuous_walkability.json",new{status=all?"PASS":"FAIL",physics="Unity Physics.CapsuleCastAll and endpointOverlapCapsule; every Environment collider included; own XR rig excluded",floorProbeSpacing=.1f,floorSamples,segments=rows});Check(all,"Continuous participant route blocked");}
 static void FinalState(){Check(!EditorApplication.isPlaying&&!EditorApplication.isCompiling,"Final state must be Edit Mode compiled");Check(SceneManager.GetActiveScene().path==ScenePath,"Final active scene");var env=Env();var ts=All();var rs=env.GetComponentsInChildren<Renderer>(true);var protectedHashes=(JObject)JObject.Parse(File.ReadAllText("Assets/VRMaintenanceResearch/AuditOutputs/V2/source_reference.json"))["protected_hashes"];var protectedRows=protectedHashes.Properties().Select(p=>new{path=p.Name,expected=(string)p.Value,actual=HashFile(p.Name),match=HashFile(p.Name)==(string)p.Value}).ToArray();Check(protectedRows.All(p=>p.match),"Protected scene changed");int missingScripts=ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));int missingMaterials=rs.Sum(r=>r.sharedMaterials.Count(m=>!m));int missingMeshes=rs.Count(r=>r is MeshRenderer&&!r.GetComponent<MeshFilter>()?.sharedMesh);var hashes=Files.ToDictionary(f=>f,f=>HashFile(Folder+"/"+f));bool sourcesMatch=Files.All(f=>hashes[f]==HashFile("D:/for_model_codex_vr_tmu/exports/environment_v2/"+f));Check(missingScripts+missingMaterials+missingMeshes==0&&sourcesMatch,"Missing reference or source mismatch");Write("final_state.json",new{status="PASS",utc=DateTime.UtcNow.ToString("o"),activeScene=SceneManager.GetActiveScene().path,sceneHash=HashFile(ScenePath),sceneDirty=SceneManager.GetActiveScene().isDirty,unity=Application.unityVersion,missingScripts,missingMaterials,missingMeshes,glbSourcesMatch=sourcesMatch,glbHashes=hashes,glassHash=HashFile(Folder+"/Materials/V2_RoomGlass_Alpha.mat"),protectedScenes=protectedRows,environmentRoot=env.name,groups=Groups.Select(n=>new{name=n,active=env.transform.Find(n).gameObject.activeSelf}).ToArray(),quest="QUEST PERFORMANCE: NOT VERIFIED ON HARDWARE"});ConsoleProbe("final_console.json");} static void Lighting(bool keep){Check(!EditorApplication.isPlaying,"Exit Play Mode");var light=All().Select(t=>t.GetComponent<Light>()).Single(l=>l&&l.type==